goal-parser-interpretation:
class Solution:
    def interpret(self, command: str) -> str:
        return command.replace('()', 'o').replace('(al)', 'al')

goat-latin:
class Solution:
    def toGoatLatin(self, sentence: str) -> str:
        out = []
        for i, w in enumerate(sentence.split()):
            if w[0] in 'aeiouAEIOU':
                out.append(w + 'ma' + 'a' * (i + 1))
            else:
                out.append(w[1:] + w[0] + 'ma' + 'a' * (i + 1))
        return ' '.join(out)

greatest-common-divisor-of-strings:
class Solution:
    def gcdOfStrings(self, str1: str, str2: str) -> str:
        if str1 + str2 != str2 + str1:
            return ''
        a = len(str1)
        b = len(str2)
        while b:
            a, b = b, a % b
        return str1[:a]

greatest-english-letter-in-upper-and-low:
class Solution:
    def greatestLetter(self, s: str) -> str:
        have = set(s)
        best = ''
        for c in have:
            if c.islower() and c.upper() in have:
                if c.upper() > best:
                    best = c.upper()
        return best

height-checker:
class Solution:
    def heightChecker(self, heights: list[int]) -> int:
        exp = sorted(heights)
        cnt = 0
        for a, b in zip(heights, exp):
            if a != b:
                cnt += 1
        return cnt

how-many-numbers-are-smaller-than-the-cu:
class Solution:
    def smallerNumbersThanCurrent(self, nums: list[int]) -> list[int]:
        s = sorted(nums)
        first = {}
        for i, v in enumerate(s):
            if v not in first:
                first[v] = i
        return [first[v] for v in nums]

increasing-decreasing-string:
class Solution:
    def sortString(self, s: str) -> str:
        cnt = {}
        for c in s:
            cnt[c] = cnt.get(c, 0) + 1
        keys = sorted(cnt)
        out = []
        remaining = len(s)
        while remaining:
            for c in keys:
                if cnt[c]:
                    out.append(c)
                    cnt[c] -= 1
                    remaining -= 1
            for c in reversed(keys):
                if cnt[c]:
                    out.append(c)
                    cnt[c] -= 1
                    remaining -= 1
        return ''.join(out)

is-subsequence:
class Solution:
    def isSubsequence(self, s: str, t: str) -> bool:
        i = 0
        for c in t:
            if i < len(s) and c == s[i]:
                i += 1
        return i == len(s)

kth-missing-positive-number:
class Solution:
    def findKthPositive(self, arr: list[int], k: int) -> int:
        have = set(arr)
        n = 1
        while True:
            if n not in have:
                k -= 1
                if k == 0:
                    return n
            n += 1

largest-odd-number-in-string:
class Solution:
    def largestOddNumber(self, num: str) -> str:
        i = len(num) - 1
        while i >= 0:
            if int(num[i]) % 2 == 1:
                return num[:i + 1]
            i -= 1
        return ''
